const familyNames:Record<string,[string,string,string]>={Citrus:['Zitrus','Agrumes','Cítricos'],Orchard:['Kernobst','Fruits à pépins','Fruta de pepita'],'Stone fruit':['Steinobst','Fruits à noyau','Fruta de hueso'],Tropical:['Tropisch','Fruits exotiques','Tropical'],'Red fruit':['Rote Frucht','Fruits rouges','Fruta roja'],'Black fruit':['Dunkle Frucht','Fruits noirs','Fruta negra'],Floral:['Blüten','Floral','Floral'],Herbal:['Kräuter','Végétal','Herbal'],Spice:['Gewürze','Épices','Especias'],'Earth & mineral':['Erde & Gestein','Terre et minéral','Tierra y mineral'],Fermentation:['Gärung','Fermentation','Fermentación'],Oak:['Holz','Bois','Roble'],Age:['Flaschenreife','Évolution','Evolución'],Concentration:['Konzentration','Concentration','Concentración'],'Wine condition':['Weinzustand','État du vin','Estado del vino']}
export function aromaContent(aroma:Aroma,locale:Locale){
  if(locale==='en')return {name:aroma.name,family:aroma.family,subfamily:aroma.subfamily,reference:aroma.reference,origin:aroma.origin,intensity:aroma.intensity}
  const index={de:0,fr:1,es:2}[locale],name=aromaNames[aroma.name]?.[index]??aroma.name,family=familyNames[aroma.family]?.[index]??aroma.family
  const copy={
    de:{reference:`Nutze ${name} als reale Duftreferenz: zuerst das Original riechen, dann Intensität und Genauigkeit im Wein vergleichen.`,origin:aroma.family==='Wine condition'?'Dieses Signal beschreibt den Zustand des Weins und kann Frucht überdecken. Kontext und Intensität entscheiden.':aroma.tier==='primary'?'Primäraroma: geprägt durch Rebsorte, Reife und Standort.':aroma.tier==='secondary'?'Sekundäraroma: entsteht oder verändert sich durch Gärung, Hefelager und Gefäß.':'Tertiäraroma: entwickelt sich während Ausbau und Flaschenreife.',intensity:['Flüchtiger Hinweis','Klar vorhanden','Prägend']},
    fr:{reference:`Utilisez ${name} comme référence réelle : sentez d’abord l’original, puis comparez précision et intensité dans le vin.`,origin:aroma.family==='Wine condition'?'Ce signal décrit l’état du vin et peut masquer le fruit. Contexte et intensité décident.':aroma.tier==='primary'?'Arôme primaire : marqué par cépage, maturité et lieu.':aroma.tier==='secondary'?'Arôme secondaire : créé ou transformé par fermentation, lies et contenant.':'Arôme tertiaire : développé pendant l’élevage et le vieillissement en bouteille.',intensity:['Suggestion fugace','Clairement présent','Note dominante']},
    es:{reference:`Usa ${name} como referencia real: huele primero el original y compara después precisión e intensidad en el vino.`,origin:aroma.family==='Wine condition'?'Esta señal describe el estado del vino y puede tapar la fruta. El contexto y la intensidad deciden.':aroma.tier==='primary'?'Aroma primario: marcado por variedad, madurez y lugar.':aroma.tier==='secondary'?'Aroma secundario: creado o transformado por fermentación, lías y recipiente.':'Aroma terciario: desarrollado durante crianza y evolución en botella.',intensity:['Sugerencia fugaz','Claramente presente','Nota dominante']},
  }[locale]
  return {name,family,subfamily:family, ...copy}
}

